CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS account_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, purpose text NOT NULL CHECK(purpose IN ('activation','reset')), expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (sid varchar PRIMARY KEY, sess json NOT NULL, expire timestamptz NOT NULL); CREATE INDEX IF NOT EXISTS sessions_expire_idx ON sessions(expire);
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value jsonb NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS repositories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), remote_uuid text UNIQUE NOT NULL, workspace text NOT NULL, slug text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT false, webhook_secret text, config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE repositories ADD COLUMN IF NOT EXISTS webhook_id text;
CREATE TABLE IF NOT EXISTS pull_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository_id uuid REFERENCES repositories ON DELETE CASCADE, number integer NOT NULL, title text NOT NULL, author text NOT NULL, source_sha text NOT NULL, destination_sha text NOT NULL, state text NOT NULL DEFAULT 'OPEN', draft boolean NOT NULL DEFAULT false, url text NOT NULL, UNIQUE(repository_id,number));
ALTER TABLE pull_requests ADD COLUMN IF NOT EXISTS summary_comment_id text;
CREATE TABLE IF NOT EXISTS review_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository_id uuid REFERENCES repositories ON DELETE CASCADE, pull_request_id uuid REFERENCES pull_requests ON DELETE CASCADE, generation integer NOT NULL DEFAULT 1, source_sha text NOT NULL, destination_sha text NOT NULL, status text NOT NULL, coverage jsonb NOT NULL DEFAULT '{}', summary text NOT NULL DEFAULT '', model text, error_code text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
ALTER TABLE review_runs ADD COLUMN IF NOT EXISTS publication_status text NOT NULL DEFAULT 'not_requested';
ALTER TABLE review_runs ADD COLUMN IF NOT EXISTS idempotency_key text UNIQUE;
ALTER TABLE review_runs ADD COLUMN IF NOT EXISTS superseded_by uuid REFERENCES review_runs(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX IF NOT EXISTS review_identity ON review_runs(pull_request_id,source_sha,destination_sha,generation);
CREATE TABLE IF NOT EXISTS findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES review_runs ON DELETE CASCADE, fingerprint text NOT NULL, path text NOT NULL, start_line integer, severity text NOT NULL, category text NOT NULL, title text NOT NULL, scenario text NOT NULL, impact text NOT NULL, evidence text NOT NULL, recommendation text NOT NULL, verified boolean NOT NULL DEFAULT false, UNIQUE(run_id,fingerprint));
CREATE TABLE IF NOT EXISTS usage_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES review_runs ON DELETE CASCADE, provider text NOT NULL, model text NOT NULL, input_tokens integer, output_tokens integer, cost_usd numeric, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users, action text NOT NULL, object_type text NOT NULL, object_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_id uuid NOT NULL REFERENCES findings ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, vote text NOT NULL CHECK(vote IN ('useful','false_positive')), reason text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(finding_id,user_id));
CREATE TABLE IF NOT EXISTS webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text UNIQUE NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, run_after timestamptz NOT NULL DEFAULT now());
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS run_after timestamptz NOT NULL DEFAULT now();
CREATE INDEX IF NOT EXISTS jobs_ready_idx ON jobs(status,run_after,created_at);
CREATE TABLE IF NOT EXISTS publication_operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES review_runs ON DELETE CASCADE, op_key text UNIQUE NOT NULL, operation text NOT NULL, status text NOT NULL DEFAULT 'pending', payload jsonb NOT NULL, remote_id text, attempts integer NOT NULL DEFAULT 0, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE publication_operations DROP CONSTRAINT IF EXISTS publication_operations_operation_check;
ALTER TABLE publication_operations ADD CONSTRAINT publication_operations_operation_check CHECK(operation IN ('summary_create','summary_update','inline_create'));
CREATE TABLE IF NOT EXISTS finding_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pull_request_id uuid NOT NULL REFERENCES pull_requests ON DELETE CASCADE, fingerprint text NOT NULL, remote_comment_id text, latest_run_id uuid REFERENCES review_runs ON DELETE SET NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(pull_request_id,fingerprint));
ALTER TABLE findings ADD COLUMN IF NOT EXISTS short_title text, ADD COLUMN IF NOT EXISTS short_impact text, ADD COLUMN IF NOT EXISTS short_fix text;
CREATE TABLE IF NOT EXISTS ai_exchanges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES review_runs ON DELETE CASCADE, kind text NOT NULL, model text NOT NULL, instructions text NOT NULL, input text NOT NULL, output text, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ai_exchanges_run_idx ON ai_exchanges(run_id, created_at);
ALTER TABLE ai_exchanges ADD COLUMN IF NOT EXISTS tools jsonb NOT NULL DEFAULT '[]';
CREATE TABLE IF NOT EXISTS prompt_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(name IN ('deteccion','verificacion','agente')), content text, created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS prompt_versions_name_idx ON prompt_versions(name, created_at DESC);
ALTER TABLE prompt_versions DROP CONSTRAINT IF EXISTS prompt_versions_name_check;
ALTER TABLE prompt_versions ADD CONSTRAINT prompt_versions_name_check CHECK(name IN ('deteccion','verificacion','agente','ficha'));
CREATE TABLE IF NOT EXISTS project_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository_id uuid NOT NULL REFERENCES repositories ON DELETE CASCADE, commit_sha text, content text NOT NULL, summary text, source text NOT NULL CHECK(source IN ('agent','edited')), created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), pr_url text);
CREATE INDEX IF NOT EXISTS project_profiles_repo_idx ON project_profiles(repository_id, created_at DESC);
